//! 🧬️ Playground artifact — document mutation dispatch. Semantic vocabulary derived from
//! `📸️snapshot/🦀️component.rs`'s `PlaygroundSnapshot` shape — a single `schema` metadata scalar;
//! this demonstrator artifact has no other structured content today, so its whole vocabulary is the
//! one metadata-only mutation `📓️derivation-rules.md` sanctions for a trivial snapshot — see
//! `.🦑️repo/🎫️tickets/🎆️26/🌙️08/☀️12/SEMANTIC-MUTATIONS-OVERHAUL/`
//! `📓️taxonomy.md`/`📓️derivation-rules.md`. `impl protocol::Mutation`/`SemanticMutation` below are
//! generated by `#[derive(dsl::Mutations)]` — never hand-written.
//!
//! The `✒️change-schema` triad leaf is mounted from `📦️glue.rs` (Wave-C trueing pass,
//! `26/08/12/SEMANTIC-MUTATIONS-OVERHAUL`) — one triad directory, one glue mount, 1:1 with this
//! enum's single variant. The old generic `🖼️set-snapshot`/`🫙no-mutation` orphan directories and
//! their glue mounts have been removed outright (no call site in this plugin ever constructed
//! either retired variant).

use crate::artifacts::playground::standards::v1::subsets::any::schema::diff::PlaygroundDiff;
use crate::artifacts::playground::standards::v1::subsets::any::schema::snapshot::PlaygroundSnapshot;
use serde::{Deserialize, Serialize};

//#region 🔖️Mutations
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, dsl::Mutations)]
#[mutations(snapshot = PlaygroundSnapshot, diff = PlaygroundDiff, schema = "s.demonstrator.playground")]
pub enum PlaygroundMutation {
    ChangeSchema(super::change_schema::mutation::ChangeSchema),
}
//#endregion 🔖️Mutations

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use protocol::{Mutation, MutationDiff, SemanticMutation};

    #[test]
    fn playground_mutation_round_trips_committed_json_bridge() {
        let before = include_str!("✒️change-schema/🧪️tests/retags-the-playground-document-schema/📸️snapshot/⬅️before/🔣️component.json");
        let mutation = include_str!("✒️change-schema/🧪️tests/retags-the-playground-document-schema/🦠️mutation/🔣️component.json");
        let after = include_str!("✒️change-schema/🧪️tests/retags-the-playground-document-schema/📸️snapshot/➡️after/🔣️component.json");
        let applied: serde_json::Value = serde_json::from_str(&apply_playground_mutation_json(before, mutation).expect("apply committed mutation")).expect("decode bridge answer");
        let expected: serde_json::Value = serde_json::from_str(after).expect("decode committed after snapshot");
        assert_eq!(applied["snapshot"], expected);
        let undone: serde_json::Value = serde_json::from_str(&undo_playground_mutation_json(before, mutation).expect("undo committed mutation")).expect("decode undo bridge answer");
        let expected: serde_json::Value = serde_json::from_str(before).expect("decode committed before snapshot");
        assert_eq!(undone["snapshot"], expected);
    }

    #[test]
    fn change_schema_inverse_round_trips() {
        let base = PlaygroundSnapshot::default();
        let mutation = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "playground.custom".into() });
        let after = mutation.diff(&base).diff().apply(&base).expect("valid mutation diff");
        assert_eq!(after.schema, "playground.custom");

        let undo = mutation.inverse(&base);
        assert_eq!(undo, vec![PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: base.schema.clone() })]);
        let mut state = after;
        for step in &undo {
            state = step.diff(&state).diff().apply(&state).expect("valid mutation diff");
        }
        assert_eq!(state, base);
    }

    #[test]
    fn semantic_kinds_cover_every_variant() {
        assert_eq!(PlaygroundMutation::kinds().len(), 1);
        let mutation = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "x".into() });
        assert_eq!(mutation.semantics().kind, "change-schema");
        assert_eq!(mutation.semantics().record, "ChangedSchema");
    }

    //#region ⚖️SemanticLaws
    /// ⚖️ `assert_mutation_inverse_law`/`assert_mutation_diff_absorb_law` (`protocol::os_spr::testkit`,
    /// reachable via this crate's existing `semio-framework-os-kernel` dependency — no new Cargo
    /// dependency needed) against the facet's one mutation kind.
    #[test]
    fn change_schema_obeys_the_inverse_and_absorb_laws() {
        let base = PlaygroundSnapshot { schema: "playground.base".into() };
        let change = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "playground.changed".into() });
        protocol::os_spr::testkit::assert_mutation_inverse_law(&base, &change);
        let d1 = change.diff(&base).into_parts().0;
        let after = d1.apply(&base).expect("valid mutation diff");
        let d2 = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "playground.changed-again".into() }).diff(&after).into_parts().0;
        protocol::os_spr::testkit::assert_mutation_diff_absorb_law(&base, d1, d2);
    }
    //#endregion ⚖️SemanticLaws

    //#region 🔖️OutcomeLaws
    /// ✅️ 26/08/16 MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS §C2 laws. This
    /// facet's one mutation kind (`change-schema`) is a root-scoped `change-<artifact>-<field>` on
    /// the document's single metadata string — no target can ever be missing and no duplicate-id
    /// case exists, so `assert_missing_target_is_error`/`assert_fatal_never_applies` do not apply
    /// here; `assert_outcome_deterministic` (landed) is the applicable law instead.
    /// `assert_outcome_policy_matrix` is not landed yet (checked at
    /// `🧰️framework/🛍️products/💻️os/🔨️modules/📡️spr/🧪️testkit/🦀️component.rs`); TODO(1-D testkit
    /// laws pending): add a `MergePolicy` × `Severity` matrix test here once it lands.
    #[test]
    fn change_schema_outcome_is_deterministic() {
        let base = PlaygroundSnapshot { schema: "playground.base".into() };
        let mutation = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "playground.changed".into() });
        protocol::os_spr::testkit::assert_outcome_deterministic(&base, &mutation);
    }

    #[test]
    fn change_schema_no_op_when_unchanged() {
        let base = PlaygroundSnapshot { schema: "playground.same".into() };
        let mutation = PlaygroundMutation::ChangeSchema(super::super::change_schema::mutation::ChangeSchema { new_schema: "playground.same".into() });
        let outcome = mutation.diff(&base);
        assert_eq!(outcome.worst_level(), Some(protocol::os_dsl::Severity::Warning));
        assert!(outcome.messages().iter().any(|message| message.code.0 == "mutation.no-op"));
    }
    //#endregion 🔖️OutcomeLaws
}
//#endregion 🧪️Tests

//#region 🌉️ExternalCodecBridge
/// 🧩️ Decodes one committed `📸️snapshot/⬅️before/🔣️component.json` document together with the
/// `🦠️mutation/🔣️component.json` payload beside it — the same bytes the leaf's own fixture test
/// reads — into real typed values.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn bridge_decode_pair(snapshot_json: &str, mutation_json: &str) -> Result<(PlaygroundSnapshot, PlaygroundMutation), String> {
    let snapshot: PlaygroundSnapshot = serde_json::from_str(snapshot_json).map_err(|error| format!("the committed playground snapshot JSON does not decode: {error}"))?;
    let mutation: PlaygroundMutation = serde_json::from_str(mutation_json).map_err(|error| format!("the committed playground mutation JSON does not decode: {error}"))?;
    Ok((snapshot, mutation))
}

/// ▶️ One diff-and-apply step, keeping the diagnostic codes the outcome raised — a rejected or
/// no-op kind is a RESULT this bridge reports, never an error it swallows.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn bridge_step(snapshot: &PlaygroundSnapshot, mutation: &PlaygroundMutation) -> Result<(PlaygroundSnapshot, Vec<String>), String> {
    use protocol::{Mutation, MutationDiff};
    let outcome = <PlaygroundMutation as Mutation<PlaygroundSnapshot>>::diff(mutation, snapshot);
    let messages: Vec<String> = outcome.messages().iter().map(|message| message.code.0.clone()).collect();
    match MutationDiff::apply(outcome.diff(), snapshot) {
        Ok(next) => Ok((next, messages)),
        Err(error) => Err(format!("{error:?}")),
    }
}

/// 📤️ The bridge's answer shape: the resulting document beside the codes it raised, so a caller
/// that cannot name `protocol::MutationOutcome` can still tell an application from a refusal.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
fn bridge_render(snapshot: &PlaygroundSnapshot, messages: Vec<String>) -> Result<String, String> {
    serde_json::to_string(&serde_json::json!({ "snapshot": snapshot, "messages": messages })).map_err(|error| error.to_string())
}

/// 🌉️ Applies one committed mutation payload to one committed before-document and answers
/// `{"snapshot": …, "messages": [ … ]}`.
///
/// The bridge exists because the generated Rust test host links only `semio-repo-test-host` and,
/// behind its `sut` feature, this crate — `serde_json`, `protocol` and `store` are private
/// extern-crate aliases (`📦️glue.rs`) and cannot be named from a case adapter. Same shape and same
/// reason as `🗄️stdio`'s `decode_semio_mesh_mutation_json`/`apply_semio_mesh_mutation` pair.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn apply_playground_mutation_json(snapshot_json: &str, mutation_json: &str) -> Result<String, String> {
    let (snapshot, mutation) = bridge_decode_pair(snapshot_json, mutation_json)?;
    let (applied, messages) = bridge_step(&snapshot, &mutation)?;
    bridge_render(&applied, messages)
}

/// ↩️ Applies one committed mutation payload and then EVERY step of its own computed inverse,
/// answering in the same shape — the metamorphic half of the evidence the `playground-mutation-semantics` no-oracle
/// decision rests on. The inverse is computed against the PRE-mutation document, which is the only
/// state that carries what a delete removed.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn undo_playground_mutation_json(snapshot_json: &str, mutation_json: &str) -> Result<String, String> {
    use protocol::Mutation;
    let (base, mutation) = bridge_decode_pair(snapshot_json, mutation_json)?;
    let (mut current, mut messages) = bridge_step(&base, &mutation)?;
    for undo in <PlaygroundMutation as Mutation<PlaygroundSnapshot>>::inverse(&mutation, &base) {
        let (next, raised) = bridge_step(&current, &undo)?;
        current = next;
        messages.extend(raised);
    }
    bridge_render(&current, messages)
}

/// 🔁️ Parses the committed `.dsl.semio` example, prints it back and parses that, answering
/// `{"printed": …, "snapshot": …, "reparsed": …}` so a caller can weigh the identity law's two
/// halves — the bytes against the committed artifact, and the projection against itself.
// 🚫️async: E1 pure codec/computation helper (file verified I/O-free, consumed via Fn-bound combinator/Display) — see R9
pub fn round_trip_playground_dsl(text: &str) -> Result<String, String> {
    use store::ArtifactDsl;
    let parsed = <PlaygroundSnapshot as ArtifactDsl>::parse_dsl(text).map_err(|error| format!("the committed playground example does not parse: {error:?}"))?;
    let printed = <PlaygroundSnapshot as ArtifactDsl>::print_dsl(&parsed);
    let reparsed = <PlaygroundSnapshot as ArtifactDsl>::parse_dsl(&printed).map_err(|error| format!("the reprinted playground document does not parse: {error:?}"))?;
    serde_json::to_string(&serde_json::json!({ "printed": printed, "snapshot": parsed, "reparsed": reparsed })).map_err(|error| error.to_string())
}
//#endregion 🌉️ExternalCodecBridge

//#region 🔖️Kinds
/// 🏷️ Kebab-case spelling of every `PlaygroundMutation` variant — one entry, because this
/// demonstrator artifact's whole persistent snapshot is one metadata string. It is the vocabulary
/// the `playground-1-any` catalog (`../../🧪️oracle/🔣️component.json`) declares and the
/// `mutate-playground-1` case measures itself against. `kinds_match_the_enum_and_the_catalog` below
/// is what keeps this list honest against the enum, since the framework never parses Rust.
pub const KINDS: &[&str] = &[
    "change-schema",
];
//#endregion 🔖️Kinds

//#region 🧪️KindsCatalog
#[cfg(test)]
mod kinds_catalog_tests {
    use super::*;
    use protocol::SemanticMutation;

    /// 🏷️ `KINDS` must name every declared variant, in the exact order and spelling
    /// `#[derive(dsl::Mutations)]` assigns, and every entry must also appear in the committed
    /// catalog — the framework reads the manifest and never parses Rust, so this test is the only
    /// thing that keeps the two in step. A plain `#[test]`: it suspends on nothing.
    #[test]
    fn kinds_match_the_enum_and_the_catalog() {
        let descriptors = PlaygroundMutation::kinds();
        assert_eq!(KINDS.len(), descriptors.len(), "KINDS must name exactly one entry per declared PlaygroundMutation variant");
        for (kind, descriptor) in KINDS.iter().zip(descriptors.iter()) {
            assert_eq!(*kind, descriptor.kind, "KINDS must match #[derive(dsl::Mutations)]'s own declaration order and spelling");
        }
        let manifest = include_str!("../../🧪️oracle/🔣️component.json");
        for kind in KINDS {
            assert!(manifest.contains(&format!("\"{kind}\"")), "KINDS entry {kind:?} must also appear in the committed playground-1-any catalog");
        }
    }
}
//#endregion 🧪️KindsCatalog
